function sportTiles(){return `<div class="sport-strip" aria-label="Modalidades">${sports.map(s=>`<a class="sport-tile ${s.open?'available':''}" href="${s.open?'#treino/'+s.id:'#modalidade/'+s.id}">${I(s.icon)}<span>${s.name}</span>${s.open?'':`<i class="tile-lock">${icon('lock')}</i>`}</a>`).join('')}</div>`}
function trainingCard(w){return `<a class="training-card" href="#treino/${w.id}"><div class="training-image"><img src="assets/${w.image}" alt="Jadiel Ferreira em uma jogada na praia" loading="lazy" width="480" height="640"><span class="pill">PRÉVIA ABERTA</span><span class="play-symbol">${icon('arrow')}</span></div><div class="training-body"><span class="eyebrow">${w.name} / BÁSICO</span><h3>${w.title}</h3><div class="training-meta"><span class="tiny-avatar"><img src="assets/jadiel.jpg" alt="" width="24" height="24" loading="lazy"></span><span>Jadiel Ferreira</span><span>Acesso antecipado</span></div></div></a>`}
