function trainings(){return `${heading('Um começo. Muitas possibilidades.','Escolha seu esporte e conheça os treinos do acesso antecipado.')}<div class="filter-bar" role="group" aria-label="Filtrar treinos"><button class="filter-chip ${currentSport==='todos'?'active':''}" data-sport="todos" aria-pressed="${currentSport==='todos'}">Todas as modalidades</button>${sports.map(s=>`<button class="filter-chip ${currentSport===s.id?'active':''}" data-sport="${s.id}" aria-pressed="${currentSport===s.id}">${s.name}${s.open?'':' · Em breve'}</button>`).join('')}</div><div id="training-results">${trainingResults()}</div><div class="section notice">${I('info')}<div><strong>O começo com Jadiel está sendo preparado.</strong><br>Você já pode explorar as páginas. As aulas e as orientações completas serão adicionadas com o conteúdo oficial.</div></div>`}
function trainingResults(){const items=workouts.filter(w=>currentSport==='todos'||w.id===currentSport);if(items.length)return `<div class="training-grid">${items.map(trainingCard).join('')}</div>`;const s=sports.find(s=>s.id===currentSport);return `<div class="empty-state">${I(s.icon)}<h2 style="margin-top:16px">${s.name} também tem lugar aqui.</h2><p>Novos treinos desta modalidade estão em desenvolvimento.<br>Enquanto isso, conheça as prévias com Jadiel.</p><button class="button" data-sport="todos">Explorar os treinos ${I('arrow')}</button></div>`}
function lesson(id){const w=workouts.find(x=>x.id===id);if(!w)return notFound();return `<a class="back-link" href="#treinos">${I('back')} Todos os treinos</a><div class="detail-layout"><div><div class="lesson-visual"><img src="assets/${w.image}" alt="Jadiel Ferreira em uma jogada na praia" width="480" height="640"><div class="lesson-overlay">${I('play')}<h2>Seu treino está a caminho.</h2><p>O conteúdo oficial com Jadiel será disponibilizado aqui. Esta é a prévia da sua página de treino.</p></div></div><div class="lesson-chapters">${w.chapters.map((c,i)=>`<div class="chapter"><span class="chapter-number">0${i+1}</span><div><strong>${c}</strong><span class="small">Conteúdo em preparação</span></div>${I('clock')}</div>`).join('')}</div></div><section class="lesson-info"><span class="eyebrow lime">${w.name} / TREINO BÁSICO</span><h1>${w.title}</h1><p>${w.description}</p>${mentor()}<div class="lesson-status"><span class="pill subtle">${I('play')} Prévia aberta</span><span class="pill subtle">Treino básico</span></div><div class="section notice">${I('info')}<p>Vídeo, exercícios, duração e instruções serão apresentados junto ao treino oficial.</p></div><div class="section"><span class="eyebrow muted">DEPOIS DO PRIMEIRO PASSO</span><h3 style="margin-top:13px">Ainda tem muito pela frente.</h3><p class="muted small" style="margin:12px 0 19px">Novos conteúdos e progressões desta modalidade estão sendo preparados.</p><button class="button secondary" data-future="Novos treinos de ${w.name.toLowerCase()}">${I('lock')} Conhecer o que vem aí</button></div></section></div>`}
function selectFilter(key,label,options){return `<label>${label}<select class="filter-select" data-event-filter="${key}">${['Todos',...options].map(o=>`<option${eventFilters[key]===o?' selected':''}>${o}</option>`).join('')}</select></label>`}
function eventPage(){return `${heading('Sua galera está em movimento.','Explore as experiências que estamos preparando para o Citra Fit.')}<div class="notice">${I('lock')}<div><strong>Uma prévia dos próximos encontros.</strong> As categorias estão abertas para explorar. Inscrições, datas e locais ainda não estão disponíveis.</div></div><div class="section"><div class="event-filters">${selectFilter('sport','Modalidade',['Corrida','Ciclismo','Natação','Híbrido','Altinha','Futevôlei'])}${selectFilter('environment','Onde você gosta de ir?',['Praia','Trilha','Cidade','Piscina'])}${selectFilter('profile','Com quem?',['Solteiros','Casais','Comunidade'])}</div><div class="section-heading"><p id="event-count" class="muted small"></p><button class="filter-chip" data-reset-events>Limpar filtros</button></div><div class="event-grid" id="event-results">${eventResults()}</div></div>`}
function eventResults(){const filtered=events.map((e,i)=>({...e,index:i})).filter(e=>Object.entries(eventFilters).every(([k,v])=>v==='Todos'||e[k]===v));return filtered.length?filtered.map(e=>`<article class="event-card"><div class="event-card-image"><img src="assets/${e.image}" alt="Prévia visual: ${e.name}" loading="lazy" width="1536" height="1024"><span class="pill">DEMO VISUAL</span><span class="event-lock">${icon('lock')}</span></div><div class="event-card-body"><div class="eyebrow">${e.sport} · ${e.environment} · ${e.profile}</div><h3>${e.name}</h3><p>${e.description}</p><button class="button secondary" data-event="${e.index}">Conhecer a experiência ${I('arrow')}</button></div></article>`).join(''):`<div class="empty-state"><h2>Novos encontros estão a caminho.</h2><p>Ainda não há uma prévia com essa combinação. Explore outras modalidades e ambientes.</p><button class="button" data-reset-events>Ver todas as experiências</button></div>`}
function club(){const benefits=[['play','Programas completos','Séries organizadas por modalidade, objetivo e nível com profissionais Citra.'],['chart','Citra Performance','Histórico, metas, evolução, recordes pessoais e leitura da sua consistência.'],['live','Lives e reprises','Treinos, técnica, IRL e lifestyle com os profissionais que você acompanha.'],['target','Desafios e recompensas','Temporadas, sequências, conquistas e benefícios desbloqueados pelo movimento.'],['event','Prioridade em eventos','Acesso antecipado, experiências reservadas e condições especiais para membros.'],['users','Vantagens com profissionais','Benefícios ao contratar acompanhamento individual dentro da plataforma.']];return `${heading('Citra Club.','Sua experiência completa de treino, evolução e comunidade.')}<section class="club-hero club-hero-expanded"><div><span class="eyebrow">MAIS DO QUE UMA ASSINATURA</span><h1>Seu esporte.<br>Seu progresso.<br>Seu Club.</h1><p>O Citra Club conecta programas, acompanhamento de evolução, profissionais, lives, desafios e experiências em um único lugar.</p><div class="club-hero-actions"><a class="button dark-button" href="#treinos">Explorar treinos ${I('arrow')}</a><button class="button outline-dark" data-club>Conhecer a proposta</button></div></div><div class="club-pass"><div class="club-pass-top"><span>CITRA FIT</span><img src="assets/citra-symbol.svg" alt=""></div><strong>CLUB MEMBER</strong><div class="club-pass-bottom"><span>MOVIMENTO QUE CONTINUA</span>${I('bolt')}</div></div></section><section class="section"><div class="section-heading"><div><h2>O Club acompanha sua rotina inteira.</h2><p>Benefícios que continuam fazendo sentido todos os meses.</p></div><span class="pill subtle">DEMO DO ECOSSISTEMA</span></div><div class="club-benefit-grid">${benefits.map(([ic,t,d],i)=>`<article class="club-benefit-card"><span class="club-benefit-number">0${i+1}</span>${I(ic)}<h3>${t}</h3><p>${d}</p><span class="pill subtle">${I('lock')} Em preparação</span></article>`).join('')}</div></section><section class="club-difference section"><div><span class="eyebrow lime">A DIFERENÇA PRECISA SER CLARA</span><h2>O Club entrega uma jornada completa. O personalizado acelera essa jornada.</h2><p>Você consegue usar o Citra Club sozinho. Quando quiser atenção individual, poderá contratar um profissional para analisar seus objetivos, adaptar o plano e acompanhar sua evolução.</p><div class="notice section">${I('check')}<div><strong>Nada de pagar para entrar em uma vitrine.</strong><br>O Club já entrega programas, recursos e experiências. O acompanhamento personalizado será sempre uma escolha adicional.</div></div></div><div class="club-compare"><article><span class="eyebrow">NO CITRA CLUB</span><h3>Treino para a comunidade</h3><ul><li>${I('check')} Programas gerais completos</li><li>${I('check')} Progressões por nível</li><li>${I('check')} Lives e reprises</li><li>${I('check')} Desafios e métricas</li></ul></article><article class="featured"><span class="eyebrow">PERSONALIZADO</span><h3>Plano criado para você</h3><ul><li>${I('check')} Avaliação individual</li><li>${I('check')} Adaptação à sua rotina</li><li>${I('check')} Feedback do profissional</li><li>${I('check')} Ajustes durante a jornada</li></ul></article></div></section><section class="section club-month"><div><div class="eyebrow lime">TODO MÊS, UM NOVO MOTIVO</div><h2>O movimento não para.</h2><p>Conteúdos, desafios e experiências renovam a jornada do membro e mantêm a comunidade ativa.</p></div><div class="club-month-grid"><article>${I('play')}<span><strong>Novos programas</strong><small>Conteúdos e progressões adicionados ao calendário.</small></span></article><article>${I('live')}<span><strong>Agenda de lives</strong><small>Encontros ao vivo e reprises para assistir no seu ritmo.</small></span></article><article>${I('medal')}<span><strong>Desafio do mês</strong><small>Metas coletivas, conquistas e recompensas por consistência.</small></span></article><article>${I('event')}<span><strong>Experiências Citra</strong><small>Eventos, encontros e ativações para sair da tela.</small></span></article></div></section><section class="club-rewards section"><div><span class="eyebrow">CITRA REWARDS</span><h2>Seu movimento desbloqueia benefícios.</h2><p>Atividades concluídas, desafios, sequências e indicações poderão gerar créditos e conquistas para usar dentro do ecossistema.</p><div class="reward-path"><span class="active">1</span><i></i><span>2</span><i></i><span>3</span><i></i><span>${I('medal')}</span></div><small>Experiência demonstrativa. Regras e condições serão apresentadas antes do lançamento.</small></div><div class="reward-card"><span class="eyebrow">SUA JORNADA</span><strong>Continue em movimento.</strong><p>Complete atividades para avançar, manter sua sequência e desbloquear o próximo benefício.</p><div class="reward-progress"><span></span></div><div class="reward-meta"><span>Sequência ativa</span><span>Próxima conquista</span></div></div></section><section class="section"><div class="section-heading"><div><h2>Feito para diferentes formas de viver o esporte.</h2><p>O membro escolhe o próprio caminho dentro da Citra.</p></div></div><div class="club-personas"><article><span class="eyebrow">QUERO COMEÇAR</span><h3>Programas e direção.</h3><p>Uma rotina organizada para sair do zero com mais segurança e consistência.</p></article><article><span class="eyebrow">QUERO EVOLUIR</span><h3>Métricas e desafios.</h3><p>Metas, histórico e estímulos para transformar esforço em progresso visível.</p></article><article><span class="eyebrow">QUERO CONEXÃO</span><h3>Comunidade e experiências.</h3><p>Feed, lives, profissionais e eventos para viver o esporte com outras pessoas.</p></article></div></section><section class="partner-cta club-cta section"><div><span class="eyebrow lime">CITRA CLUB / ACESSO ANTECIPADO</span><h2>Isso ainda é só uma prévia.</h2><p>Benefícios finais, regras e condições serão apresentados na abertura oficial.</p></div><div><button class="button" data-club>Quero acompanhar ${I('arrow')}</button></div></section>`}
function affiliates(){const paths=[['play','Citra Pro','Ensine dentro da Citra','Publique programas, ofereça acompanhamento personalizado e construa sua comunidade.','Quero ensinar'],['spark','Afiliado Citra','Indique e cresça junto','Compartilhe seu link, apresente o Citra e acompanhe cada indicação pelo seu painel.','Quero indicar'],['live','Citra Creator','Conteúdo, influência e esporte','Faça lives, crie desafios, compartilhe sua rotina e também indique o Citra.','Quero fazer os dois']];return `${heading('Ganhe com a Citra.','Escolha como seu conhecimento ou sua influência podem se transformar em oportunidade.')}<section class="affiliate-hero partners-hero"><div><span class="eyebrow lime">CITRA PARTNERS / DEMONSTRAÇÃO</span><h1>Ensine. Indique.<br>Movimente pessoas.</h1><p>Profissionais, atletas e criadores poderão construir audiência, oferecer experiências e acompanhar sua evolução dentro do ecossistema Citra.</p><div class="partner-hero-actions"><button class="button" data-partner-apply="Quero ensinar">Conhecer os caminhos ${I('arrow')}</button><span class="pill subtle">${I('lock')} Candidaturas em breve</span></div></div><div class="affiliate-mark" aria-label="Citra Partners">C<span>+</span>VOCÊ</div></section><section class="section"><div class="section-heading"><div><h2>Como você quer crescer?</h2><p>Os caminhos podem funcionar separados ou juntos.</p></div></div><div class="partner-paths">${paths.map(([ic,name,title,description,action])=>`<article class="partner-path">${I(ic)}<span class="eyebrow">${name}</span><h3>${title}</h3><p>${description}</p><button class="text-link" data-partner-preview="${name}">${action} ${I('arrow')}</button></article>`).join('')}</div></section><section class="partner-flow section"><div><span class="eyebrow lime">PARA QUEM ENSINA</span><h2>Conhecimento que continua gerando valor.</h2><p>O profissional poderá participar dos conteúdos do Club, oferecer programas, vender acompanhamento individual e desbloquear transmissões ao vivo conforme sua evolução.</p><div class="partner-feature-list"><div>${I('play')}<span><strong>Programas no Club</strong><small>Treinos gerais organizados por modalidade e objetivo.</small></span></div><div>${I('user')}<span><strong>Acompanhamento personalizado</strong><small>Uma experiência individual, separada dos conteúdos gerais.</small></span></div><div>${I('live')}<span><strong>Lives e experiências</strong><small>Treino, técnica, IRL, lifestyle e encontros com a comunidade.</small></span></div></div></div><div class="partner-dashboard"><div class="dashboard-top"><div><span class="eyebrow">PAINEL PROFISSIONAL</span><strong>Visão geral</strong></div><span class="status-dot">DEMO</span></div><div class="dashboard-metrics"><div><span>Alunos ativos</span><strong>128</strong><small>com você este mês</small></div><div><span>Treinos concluídos</span><strong>642</strong><small>engajamento real</small></div><div><span>Avaliação</span><strong>4,9</strong><small>qualidade percebida</small></div></div><div class="dashboard-line"><span style="height:31%"></span><span style="height:47%"></span><span style="height:39%"></span><span style="height:62%"></span><span style="height:70%"></span><span style="height:88%"></span><span style="height:82%"></span></div><p>Ganhos, repasses e desempenho aparecerão aqui quando o programa estiver ativo.</p></div></section><section class="section"><div class="section-heading"><div><h2>Mais de uma forma de ganhar.</h2><p>Sem valores exibidos nesta demonstração.</p></div></div><div class="earning-grid">${[['club','Conteúdo do Citra Club','Participação baseada no uso e na qualidade dos conteúdos.'],['user','Serviços personalizados','Venda de acompanhamento, análise e programas individuais.'],['live','Lives e experiências','Aulas coletivas, encontros e formatos especiais.'],['spark','Indicações confirmadas','Acompanhamento de novos membros trazidos pelo seu link.']].map(([ic,t,d])=>`<article>${I(ic)}<h3>${t}</h3><p>${d}</p><span class="pill subtle">Modelo em definição</span></article>`).join('')}</div></section><section class="section affiliate-system"><div><span class="eyebrow lime">PARA QUEM INDICA</span><h2>Seu link. Sua comunidade. Seu painel.</h2><p>Cada parceiro terá um link, código e QR Code próprios para apresentar o Club, eventos e experiências Citra.</p><ol class="steps compact"><li><span>01 / COMPARTILHE</span><h3>Divulgue do seu jeito.</h3><p>Use seu link ou código nas redes, grupos e conteúdos.</p></li><li><span>02 / ACOMPANHE</span><h3>Veja o caminho.</h3><p>Cliques, cadastros e indicações confirmadas no painel.</p></li><li><span>03 / RECEBA</span><h3>Ganhe por resultado.</h3><p>Repasses vinculados a vendas reais e dentro das regras do programa.</p></li></ol></div><div class="affiliate-code-card"><span class="eyebrow">SEU LINK CITRA</span><div class="fake-link"><span>citra.fit/seuusuario</span><button aria-label="Copiar link demonstrativo" data-copy-demo>${I('check')}</button></div><div class="affiliate-kpis"><div><strong>1.284</strong><span>Cliques</span></div><div><strong>86</strong><span>Ativos</span></div></div><span class="pill subtle">${I('lock')} Painel demonstrativo</span></div></section><section class="section"><div class="section-heading"><div><h2>Lives são uma conquista.</h2><p>A liberação considera segurança, qualidade e participação real.</p></div></div><div class="unlock-track"><article class="done">${I('check')}<div><span>Identidade</span><strong>Perfil verificado</strong></div></article><article>${I('play')}<div><span>Conteúdo</span><strong>Materiais aprovados</strong></div></article><article>${I('users')}<div><span>Comunidade</span><strong>Participação e avaliações</strong></div></article><article>${I('live')}<div><span>Desbloqueio</span><strong>Lives liberadas</strong></div></article></div></section><section class="section partner-rules"><div><span class="eyebrow">REGRAS ESSENCIAIS</span><h2>Crescimento de verdade.</h2></div><div class="rules-grid"><p>${I('check')} Ninguém paga para indicar.</p><p>${I('check')} Não existe ganho por recrutar afiliados.</p><p>${I('check')} Repasses dependem de vendas confirmadas.</p><p>${I('check')} Conteúdo e publicidade precisam ser transparentes.</p></div></section><section class="partner-cta section"><div><span class="eyebrow lime">CITRA PARTNERS</span><h2>Qual caminho combina com você?</h2><p>Explore uma simulação da candidatura. Nenhuma informação será enviada nesta demo.</p></div><div><button class="button" data-partner-apply="Quero ensinar">Quero ensinar ${I('arrow')}</button><button class="button secondary" data-partner-apply="Quero indicar">Quero indicar</button><button class="button secondary" data-partner-apply="Quero fazer os dois">Quero fazer os dois</button></div></section>`}
function launch(welcome=false){return `<section class="launch-page"><span class="eyebrow">CITRA FIT / ACESSO ANTECIPADO</span><h1>${welcome?'Você chegou<br>antes. E faz parte.':'O seu próximo<br>capítulo está chegando.'}</h1><p>${welcome?'Bem-vindo à prévia do Citra Fit. Conheça os treinos com Jadiel, explore as modalidades e descubra as experiências que vêm aí.':'Enquanto preparamos o lançamento, você já pode explorar o universo Citra e conhecer os primeiros conteúdos.'}</p>${welcome?'<div class="welcome-visual"><img src="assets/rio-beach.jpg" alt="Praia ao pôr do sol" width="900" height="300"></div>':`<div class="countdown" aria-label="Contagem para o lançamento">${['Dias','Horas','Minutos','Segundos'].map((t,i)=>`<div><strong data-count="${i}">—</strong><span>${t}</span></div>`).join('')}</div><p id="launch-status" class="small">A data oficial será anunciada em breve.</p>`}<a href="${welcome?'#lancamento':'#inicio'}" class="button">${welcome?'Acompanhar o lançamento':'Explorar o preview'} ${I('arrow')}</a>${welcome?'<p class="small" style="margin-top:18px"><a class="text-link" href="#inicio">Ir direto para o meu espaço</a></p>':''}<div class="notice">${I('spark')}<div><strong>Fique de olho no seu espaço.</strong><br>Novidades e conteúdos aparecerão aqui conforme forem disponibilizados.</div></div></section>`}
function settings(){return `${heading('Seu espaço.','Acompanhe o próximo capítulo e deixe o Citra com a sua cara.')}<div class="settings-grid"><section class="settings-card"><h2>Seu acesso antecipado</h2><a class="settings-row" href="#feed">${I('feed')}<span>Feed<small>Atividades e conquistas da comunidade</small></span>${I('arrow')}</a><a class="settings-row" href="#lives">${I('live')}<span>Lives<small>Treino, IRL e lifestyle</small></span>${I('arrow')}</a><a class="settings-row" href="#gravar">${I('map')}<span>Gravar atividade<small>Localização, mapa e métricas em tempo real</small></span>${I('arrow')}</a><a class="settings-row" href="#boas-vindas">${I('bolt')}<span>Boas-vindas<small>Conheça a experiência de pré-venda</small></span>${I('arrow')}</a><a class="settings-row" href="#lancamento">${I('clock')}<span>Lançamento<small>Acompanhe a abertura do Citra Fit</small></span>${I('arrow')}</a><a class="settings-row" href="#afiliados">${I('spark')}<span>Ganhe com a Citra<small>Ensine, indique ou faça os dois</small></span>${I('arrow')}</a><a class="settings-row" href="#evolucao">${I('chart')}<span>Sua evolução<small>Descubra o que está por vir</small></span>${I('arrow')}</a></section><section class="settings-card"><h2>Do seu jeito</h2><div class="settings-row">${I('sun')}<span>Aparência<small id="theme-label"></small></span><button class="button secondary" data-theme-toggle>Trocar tema</button></div><p class="muted small" style="margin-top:15px">Sua escolha de tema fica salva neste navegador.</p><div class="notice section">${I('info')}<div>Você está explorando uma versão de apresentação. O acesso vinculado à compra será disponibilizado na abertura da pré-venda.</div></div></section></div>`}
function evolution(){return `${heading('Cada movimento vai contar.','Uma prévia de como você poderá acompanhar sua jornada.')}<div class="future-grid">${[['chart','Seu progresso','Acompanhe a evolução das suas atividades ao longo do tempo.'],['target','Seus objetivos','Visualize as metas que dão direção à sua rotina.'],['medal','Suas conquistas','Celebre os marcos da sua jornada no esporte.']].map(([ic,t,d],i)=>`<article class="future-card">${I(ic)}<h3>${t}</h3><p>${d}</p><span class="pill subtle">${I('lock')} Em desenvolvimento</span>${i===0?'<div class="sample-bars" aria-hidden="true"><span style="height:20%"></span><span style="height:34%"></span><span style="height:42%"></span><span style="height:60%"></span><span style="height:72%"></span><span style="height:87%"></span></div><div class="preview-caption">Visual ilustrativo • sem dados de atividade</div>':''}<button class="button secondary" data-future="${t}">Conhecer a proposta ${I('arrow')}</button></article>`).join('')}</div><div class="notice">${I('lock')}<p>Histórico, metas e conquistas estarão disponíveis em uma próxima etapa do Citra Fit.</p></div>`}
function feed(){return `${heading('O movimento acontece aqui.','Treinos, evolução e lifestyle compartilhados pela comunidade.')}<section class="live-strip"><div class="live-strip-copy"><span class="live-dot"></span><div><strong>Lives dos profissionais</strong><span>Treino, IRL e lifestyle em tempo real.</span></div></div><a class="button live-button" href="#lives">Explorar lives ${I('arrow')}</a></section><div class="feed-layout"><div class="feed-main"><section class="composer"><div class="composer-top"><span class="feed-avatar">L</span><button data-new-post>Como foi o seu treino hoje?</button></div><div class="composer-actions"><button data-new-post>${I('camera')} Foto</button><button data-new-post>${I('chart')} Marcar atividade</button><button data-new-post>${I('spark')} Compartilhar evolução</button></div></section><article class="post-card"><div class="post-head"><span class="feed-avatar jadiel-avatar"><img src="assets/jadiel-futevolei.jpg" alt="Jadiel Ferreira"></span><div><strong>Jadiel Ferreira</strong><span>Futevôlei · agora mesmo</span></div><span class="pill subtle">PROFISSIONAL</span></div><p>Movimento, controle e consistência. Mais uma sessão na quadra concluída.</p><img class="post-image" src="assets/jadiel-futevolei.jpg" alt="Jadiel Ferreira com uma bola na quadra"><div class="post-stats"><strong>Treino técnico</strong><span>52 min</span><span>Intensidade alta</span></div><div class="post-actions"><button>${I('heart')} 1.284</button><button>${I('comment')} 96 comentários</button></div></article><article class="post-card"><div class="post-head"><span class="feed-avatar">MC</span><div><strong>Marina Costa</strong><span>Corrida · hoje, 07:12</span></div></div><p>Primeiros 5 km sem parar. Achei que não ia conseguir, mas fui até o fim. ⚡</p><div class="mini-route"><div class="route-grid"></div><span class="route-path"></span><span class="route-pin start"></span><span class="route-pin finish"></span></div><div class="post-stats"><strong>5,02 km</strong><span>31:44</span><span>6:19/km</span></div><div class="post-actions"><button>${I('heart')} 214</button><button>${I('comment')} 18 comentários</button></div></article></div><aside class="feed-side"><div class="settings-card"><span class="eyebrow lime">AGORA NO CITRA</span><h2 style="margin-top:12px">Uma comunidade que se movimenta junto.</h2><p class="muted">Siga profissionais, veja atividades e compartilhe cada conquista.</p><div class="section notice">${I('lock')}<div><strong>Feed demonstrativo.</strong><br>Publicação e perfis sociais serão liberados no aplicativo.</div></div></div></aside></div>`}
function lives(){return `${heading('Ao vivo, no ritmo deles.','Profissionais elegíveis poderão transmitir treinos, IRL e lifestyle.')}<section class="live-hero"><img src="assets/jadiel-musculacao.jpg" alt="Jadiel Ferreira treinando na academia"><div class="live-hero-overlay"><span class="live-badge"><span class="live-dot"></span> LIVE DEMO</span><span class="eyebrow">TREINO / JADIEL FERREIRA</span><h1>Treino de musculação<br>sem cortes.</h1><p>Acompanhe profissionais durante o treino e veja de perto a rotina por trás da evolução.</p><button class="button" data-live-notify>Avise-me quando começar ${I('arrow')}</button></div></section><div class="live-grid">${[['jadiel-futevolei.jpg','Treino','Futevôlei na prática','Jadiel Ferreira'],['evento-trilha.webp','IRL','Dia de trilha com a comunidade','Profissionais Citra'],['rio-beach.jpg','Lifestyle','Rotina, praia e movimento','Profissionais Citra']].map(([img,cat,title,who])=>`<article class="live-card"><div class="live-thumb"><img src="assets/${img}" alt="Prévia de ${cat.toLowerCase()}"><span class="pill">${I('lock')} EM BREVE</span><span class="live-play">${icon('play')}</span></div><div><span class="eyebrow">${cat}</span><h3>${title}</h3><p>${who}</p></div></article>`).join('')}</div><div class="notice section">${I('info')}<div><strong>Lives serão uma conquista profissional.</strong><br>O recurso será liberado para profissionais que atingirem os critérios definidos pelo Citra Fit. As transmissões acima são prévias visuais.</div></div>`}
function record(){return `${heading('Grave seu movimento.','Localização refinada, ajuste manual e percurso em tempo real.')}<div class="record-layout"><section class="map-shell"><div id="activity-map" aria-label="Mapa interativo com a localização do visitante"></div><div class="map-demo-badge" id="location-badge">${I('map')} BUSCANDO MELHOR SINAL</div><div class="map-controls"><button class="map-locate-button" data-locate aria-label="Buscar localização com mais precisão">${I('target')} Melhorar precisão</button><button class="map-adjust-button" data-adjust-location aria-label="Ajustar meu ponto diretamente no mapa">${I('map')} Ajustar no mapa</button></div><div class="accuracy-panel" id="accuracy-panel"><span>PRECISÃO</span><strong id="accuracy-value">—</strong></div></section><aside class="record-panel"><span class="eyebrow lime">NOVA ATIVIDADE</span><div class="location-card" data-state="loading"><span class="location-pulse"></span><div><strong id="location-title">Buscando o melhor sinal...</strong><small id="location-status">A Citra compara novas leituras e mantém a mais precisa.</small></div><div class="location-actions"><button class="button secondary" id="locate-button" data-locate>Buscar novamente</button><button class="button secondary" data-adjust-location>Ajustar manualmente</button></div></div><label class="record-label">Modalidade<select id="record-sport" class="filter-select"><option>Corrida</option><option>Caminhada</option><option>Ciclismo</option><option>Natação em águas abertas</option></select></label><div class="record-metrics"><div><strong id="record-time">00:00</strong><span>Tempo</span></div><div><strong id="record-distance">0,00</strong><span>km</span></div><div><strong id="record-pace">—</strong><span>Ritmo</span></div></div><button class="record-button" id="record-button" data-record-start>${I('play')} Iniciar atividade</button><p class="small muted">Nesta demo, sua localização fica no navegador. Se o computador fornecer uma posição ampla, use “Ajustar no mapa” para marcar o ponto exato.</p></aside></div><section class="section map-explainer"><div><span class="eyebrow lime">COMO A PRECISÃO FUNCIONA</span><h2>O mapa mostra. O aparelho localiza.</h2><p>A Citra busca várias leituras do GPS ou da rede, escolhe a mais precisa e exibe o raio de confiança. Em celulares com localização precisa ativada, o resultado tende a melhorar.</p></div><div class="map-quality"><article><span class="quality-dot high"></span><div><strong>Alta precisão</strong><small>GPS pronto para atividade.</small></div></article><article><span class="quality-dot medium"></span><div><strong>Precisão moderada</strong><small>Aguardando uma leitura melhor.</small></div></article><article><span class="quality-dot low"></span><div><strong>Precisão baixa</strong><small>Ajuste manual disponível.</small></div></article></div></section><section class="section outdoor-sports"><div class="section-heading"><div><h2>Feito para ir com você.</h2><p>Escolha a modalidade e acompanhe seu percurso em tempo real.</p></div></div><div class="benefit-grid"><article class="benefit">${I('run')}<h3>Corrida e caminhada</h3><p>Distância, tempo, ritmo e caminho percorrido.</p></article><article class="benefit">${I('bike')}<h3>Ciclismo</h3><p>Rota, velocidade e evolução sobre duas rodas.</p></article><article class="benefit">${I('swim')}<h3>Natação ao ar livre</h3><p>Uma prévia para registrar percursos em águas abertas.</p></article></div></section>`}
function modality(id){const s=sports.find(x=>x.id===id);if(!s)return notFound();return `<a class="back-link" href="#treinos">${I('back')} Todas as modalidades</a>${heading(s.name,'Seu próximo esporte também tem lugar no Citra.')}<div class="empty-state">${I(s.icon)}<h2 style="margin-top:20px">Uma nova forma de se movimentar.</h2><p>Os treinos de ${s.name.toLowerCase()} estão em desenvolvimento.<br>Conteúdos, orientações e novidades serão apresentados por aqui.</p><span class="pill subtle">${I('lock')} Em breve</span><div style="margin-top:25px"><a class="button" href="#treinos">Conhecer os treinos com Jadiel ${I('arrow')}</a></div></div>`}
function notFound(){return `<div class="empty-state"><h1>Vamos voltar ao seu espaço?</h1><p>Essa página não está disponível no preview.</p><a href="#inicio" class="button">Voltar ao início</a></div>`}
function render(){clearInterval(countdownInterval);clearInterval(recordInterval);stopGeoWatch();if(dialog.open)dialog.close();const [route='inicio',id]=location.hash.slice(1).split('/');const renders={inicio:home,feed,lives,gravar:record,treinos:trainings,eventos:eventPage,club,afiliados:affiliates,lancamento:()=>launch(), 'boas-vindas':()=>launch(true),mais:settings,evolucao:evolution,treino:()=>lesson(id),modalidade:()=>modality(id)};main.innerHTML=`<div class="fade-in">${(renders[route]||notFound)()}</div>`;const active=['treino','modalidade'].includes(route)?'treinos':['afiliados','lancamento','boas-vindas','evolucao','lives'].includes(route)?'mais':route;document.querySelectorAll('[data-nav]').forEach(a=>{const desktop=a.closest('#desktop-nav');const wanted=desktop?(['treino','modalidade'].includes(route)?'treinos':route):active;const isActive=a.dataset.nav===wanted;a.classList.toggle('active',isActive);if(isActive)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const names={inicio:'Seu espaço',feed:'Feed',lives:'Lives',gravar:'Gravar atividade',treinos:'Treinos',treino:'Treino com Jadiel',modalidade:'Modalidades',eventos:'Eventos',club:'Citra Club',afiliados:'Citra Partners',mais:'Seu espaço',evolucao:'Sua evolução',lancamento:'Lançamento','boas-vindas':'Boas-vindas'};document.getElementById('breadcrumb').textContent=names[route]||'Preview';document.title=`Citra Fit — ${names[route]||'Preview'}`;hydrateIcons();updateThemeLabel();updateEventCount();updateMobileNavIndicator(route);if(route==='lancamento')startCountdown();if(route==='gravar')requestAnimationFrame(initActivityMap);window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
function updateEventCount(){const count=document.getElementById('event-count');if(count){const n=events.filter(e=>Object.entries(eventFilters).every(([k,v])=>v==='Todos'||e[k]===v)).length;count.textContent=`${n} ${n===1?'experiência prevista':'experiências previstas'}`}}
function startCountdown(){if(!CONFIG.launchAt)return;const end=Date.parse(CONFIG.launchAt);if(!Number.isFinite(end))return;const tick=()=>{const diff=Math.max(0,Math.floor((end-Date.now())/1000));const values=[Math.floor(diff/86400),Math.floor(diff/3600)%24,Math.floor(diff/60)%60,diff%60];document.querySelectorAll('[data-count]').forEach((el,i)=>el.textContent=String(values[i]).padStart(2,'0'));document.getElementById('launch-status').textContent=diff?'Lançamento em '+new Date(end).toLocaleString('pt-BR',{dateStyle:'long',timeStyle:'short'})+'.':'O momento chegou. Acompanhe as novidades no seu espaço.';if(!diff)clearInterval(countdownInterval)};tick();countdownInterval=setInterval(tick,1000)}
function updateThemeLabel(){const dark=document.documentElement.dataset.theme==='dark';const toggle=document.getElementById('theme-toggle');toggle.innerHTML=icon(dark?'sun':'moon');toggle.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo escuro');document.querySelector('meta[name="theme-color"]').content=dark?'#0f1419':'#f3f0e8';const label=document.getElementById('theme-label');if(label)label.textContent=dark?'Modo escuro · grafite':'Modo claro · off-white'}
function toggleTheme(){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('citra-theme',theme)}catch{}updateThemeLabel()}
function initActivityMap(){const mapEl=document.getElementById('activity-map');if(!mapEl)return;if(typeof L==='undefined'){mapEl.innerHTML='<div class="map-fallback"><strong>Mapa da atividade</strong><span>A visualização interativa precisa de conexão.</span></div>';setLocationUI('error','Mapa indisponível','Conecte-se à internet para carregar o mapa.');return}activityMap=L.map(mapEl,{zoomControl:false,attributionControl:true}).setView([-22.9068,-43.1729],11);L.control.zoom({position:'bottomright'}).addTo(activityMap);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(activityMap);activityLine=L.polyline([],{color:'#c6ff3d',weight:5,opacity:.95,lineCap:'round',lineJoin:'round'}).addTo(activityMap);activityMap.on('click',event=>{if(!manualAdjust)return;manualLocation=true;const position={coords:{latitude:event.latlng.lat,longitude:event.latlng.lng,accuracy:8}};showVisitorLocation(position,false,false,true);manualAdjust=false;mapEl.classList.remove('manual-adjust');setLocationUI('ready','Ponto ajustado no mapa','Este será o ponto inicial desta demonstração.');document.querySelectorAll('[data-adjust-location]').forEach(button=>button.classList.remove('active'))});locateVisitor()}
function setLocationUI(state,title,message){const card=document.querySelector('.location-card');const titleEl=document.getElementById('location-title');const statusEl=document.getElementById('location-status');if(card)card.dataset.state=state;if(titleEl)titleEl.textContent=title;if(statusEl)statusEl.textContent=message}
function stopGeoWatch(){if(geoWatchId!==undefined&&navigator.geolocation){navigator.geolocation.clearWatch(geoWatchId);geoWatchId=undefined}clearTimeout(refinementTimer)}
function showVisitorLocation(position,center=true,tracking=false,forced=false){if(!activityMap)return;const accuracy=Math.max(1,Math.round(position.coords.accuracy||9999));if(!forced&&!tracking&&accuracy>=bestAccuracy)return;if(!forced&&!tracking)bestAccuracy=accuracy;const point=[position.coords.latitude,position.coords.longitude];currentPosition=position;if(!activityMarker){activityMarker=L.circleMarker(point,{radius:9,color:'#10150f',weight:3,fillColor:'#c6ff3d',fillOpacity:1}).addTo(activityMap).bindPopup('Você está aqui');accuracyCircle=L.circle(point,{radius:accuracy,color:'#c6ff3d',weight:1,fillColor:'#c6ff3d',fillOpacity:.08}).addTo(activityMap)}else{activityMarker.setLatLng(point);accuracyCircle?.setLatLng(point).setRadius(accuracy)}if(center){const zoom=accuracy>1000?13:accuracy>300?14:accuracy>100?15:17;activityMap.setView(point,zoom,{animate:true})}const quality=accuracy<=50?'high':accuracy<=250?'medium':'low';const message=forced?'Ponto definido manualmente para esta demonstração.':accuracy<=50?`Alta precisão: margem aproximada de ${accuracy} metros.`:accuracy<=250?`Precisão moderada: margem aproximada de ${accuracy} metros. Buscando melhorar...`:`Precisão baixa: margem aproximada de ${accuracy} metros. Ative a localização precisa ou ajuste o ponto no mapa.`;setLocationUI(tracking?'tracking':quality,tracking?'Gravação em andamento':forced?'Ponto ajustado':'Localização encontrada',message);const accuracyValue=document.getElementById('accuracy-value');if(accuracyValue)accuracyValue.textContent=forced?'AJUSTADA':`${accuracy} m`;const accuracyPanel=document.getElementById('accuracy-panel');if(accuracyPanel)accuracyPanel.dataset.quality=forced?'high':quality;const badge=document.getElementById('location-badge');if(badge)badge.innerHTML=`${I('target')} ${forced?'PONTO AJUSTADO':quality==='high'?'SINAL PRECISO':quality==='medium'?'REFINANDO SINAL':'SINAL APROXIMADO'}`;if(!tracking&&accuracy<=35)stopGeoWatch();if(tracking){if(!forced&&accuracy>120)return;const previous=liveRoute[liveRoute.length-1];if(previous){const segment=activityMap.distance(previous,point);const noiseFloor=Math.max(3,accuracy*.25);if(segment>noiseFloor&&segment<500)liveDistance+=segment;else if(segment<=noiseFloor)return}liveRoute.push(point);activityLine.setLatLngs(liveRoute);document.getElementById('record-distance').textContent=(liveDistance/1000).toFixed(2).replace('.',',')}}
function handleLocationError(error){const messages={1:'Permissão negada. Libere a localização precisa nas configurações do navegador.',2:'O aparelho não conseguiu determinar uma posição confiável.',3:'A localização demorou para responder. Tente novamente ao ar livre ou pelo celular.'};stopGeoWatch();setLocationUI('error','Localização não disponível',messages[error?.code]||'Tente novamente ou ajuste o ponto diretamente no mapa.');const badge=document.getElementById('location-badge');if(badge)badge.innerHTML=`${I('info')} LOCALIZAÇÃO NÃO LIBERADA`}
function locateVisitor(){if(!navigator.geolocation){setLocationUI('error','Recurso não disponível','Este navegador não oferece acesso à localização.');return}stopGeoWatch();manualLocation=false;currentPosition=undefined;bestAccuracy=Infinity;setLocationUI('loading','Buscando o melhor sinal...','Comparando leituras para reduzir a margem de erro.');const badge=document.getElementById('location-badge');if(badge)badge.innerHTML=`${I('target')} BUSCANDO MELHOR SINAL`;geoWatchId=navigator.geolocation.watchPosition(position=>showVisitorLocation(position,true,false),handleLocationError,{enableHighAccuracy:true,timeout:20000,maximumAge:0});refinementTimer=setTimeout(()=>{if(!recordInterval)stopGeoWatch();if(currentPosition&&Number.isFinite(bestAccuracy)&&bestAccuracy>250)setLocationUI('low','Localização aproximada',`O aparelho informou uma margem de ${Math.round(bestAccuracy)} metros. Ative a localização precisa ou ajuste o ponto no mapa.`)},18000)}
function toggleManualAdjust(button){if(!activityMap)return;manualAdjust=!manualAdjust;document.getElementById('activity-map')?.classList.toggle('manual-adjust',manualAdjust);document.querySelectorAll('[data-adjust-location]').forEach(item=>item.classList.toggle('active',manualAdjust));if(manualAdjust){stopGeoWatch();setLocationUI('manual','Toque no ponto exato','Mova o mapa e toque onde você realmente está.');const badge=document.getElementById('location-badge');if(badge)badge.innerHTML=`${I('map')} AJUSTE MANUAL ATIVO`;button?.blur()}else if(currentPosition){setLocationUI('ready','Ajuste cancelado','Sua última localização foi mantida.')}}
function toggleRecording(button){if(recordInterval){clearInterval(recordInterval);recordInterval=null;stopGeoWatch();button.innerHTML=`${I('check')} Atividade encerrada`;button.classList.remove('is-recording');button.disabled=true;setLocationUI('ready','Atividade concluída','Seu percurso ficou somente nesta demonstração.');return}if(!currentPosition){locateVisitor();setLocationUI('loading','Precisamos da sua localização','Autorize o acesso ou ajuste seu ponto e toque novamente em iniciar.');return}recordSeconds=0;liveDistance=0;liveRoute=[];activityLine?.setLatLngs([]);stopGeoWatch();button.classList.add('is-recording');button.innerHTML='<span class="record-pulse"></span> Encerrar atividade';setLocationUI('tracking','Gravação em andamento','Somente leituras confiáveis entram no percurso.');geoWatchId=navigator.geolocation.watchPosition(position=>{if((position.coords.accuracy||9999)>120){setLocationUI('low','Sinal insuficiente para gravar',`Margem atual de ${Math.round(position.coords.accuracy)} metros. Aguardando um sinal melhor...`);return}showVisitorLocation(position,false,true)},handleLocationError,{enableHighAccuracy:true,timeout:20000,maximumAge:0});const update=()=>{recordSeconds++;const min=Math.floor(recordSeconds/60);const sec=recordSeconds%60;document.getElementById('record-time').textContent=`${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;if(liveDistance>10){const paceSeconds=recordSeconds/(liveDistance/1000);const paceMin=Math.floor(paceSeconds/60);const paceSec=Math.floor(paceSeconds%60);document.getElementById('record-pace').textContent=`${paceMin}:${String(paceSec).padStart(2,'0')}`}};update();recordInterval=setInterval(update,1000)}
function openPostComposer(){lastDialogTrigger=document.activeElement;document.getElementById('dialog-content').innerHTML=`<div class="dialog-content composer-dialog"><div class="dialog-emblem">${I('camera')}</div><span class="pill subtle">FEED DEMONSTRATIVO</span><h2 id="dialog-title">Compartilhe seu treino.</h2><label>Modalidade<select id="post-sport" class="filter-select"><option>Corrida</option><option>Musculação</option><option>Altinha</option><option>Futevôlei</option><option>Ciclismo</option><option>Natação</option></select></label><label>Como foi?<textarea id="post-text" rows="4" placeholder="Conte como foi o seu movimento hoje..."></textarea></label><label class="upload-demo">${I('camera')} Adicionar uma foto<input id="post-photo" type="file" accept="image/*"></label><div id="post-photo-name" class="small muted">Nenhuma foto selecionada.</div><button class="button" data-publish-demo>Publicar demonstração ${I('arrow')}</button></div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal()}
function publishDemoPost(){const sport=document.getElementById('post-sport')?.value||'Treino';const text=document.getElementById('post-text')?.value.trim()||'Mais um treino concluído. ⚡';dialog.close();const feedMain=document.querySelector('.feed-main');if(!feedMain)return;feedMain.insertAdjacentHTML('afterbegin',`<article class="post-card demo-post"><div class="post-head"><span class="feed-avatar">L</span><div><strong>Você</strong><span>${sport} · agora mesmo</span></div><span class="pill subtle">DEMO</span></div><p>${text.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}</p><div class="post-stats"><strong>Atividade compartilhada</strong><span>Visível somente nesta prévia</span></div><div class="post-actions"><button>${I('heart')} Curtir</button><button>${I('comment')} Comentar</button></div></article>`);hydrateIcons(feedMain)}
function openPartnerPreview(type){const content={"Citra Pro":['Ensine dentro da Citra.','Crie programas gerais para o Club, ofereça acompanhamento individual, acompanhe alunos e evolua até liberar lives e experiências.'],"Afiliado Citra":['Leve o movimento para sua comunidade.','Use um link, código e QR Code próprios. O painel mostrará cliques, indicações confirmadas e repasses quando o programa estiver ativo.'],"Citra Creator":['Transforme conteúdo em conexão.','Compartilhe rotina, esporte e lifestyle, participe de desafios, desbloqueie lives e combine criação com indicações.']}[type]||['Citra Partners.','Escolha ensinar, indicar ou combinar os dois caminhos.'];openDialog(content[0],`<p>${content[1]}</p><p><strong>Esta experiência é demonstrativa.</strong> Critérios, repasses e condições finais ainda serão apresentados.</p>`,type)}
function openPartnerApplication(role){lastDialogTrigger=document.activeElement;document.getElementById('dialog-content').innerHTML=`<div class="dialog-content partner-form"><div class="dialog-emblem">${I('spark')}</div><span class="pill subtle">CANDIDATURA DEMO</span><h2 id="dialog-title">Seu caminho na Citra.</h2><p>Preencha para visualizar a experiência. Nenhum dado será enviado ou armazenado.</p><label>Quero participar como<select id="partner-role" class="filter-select"><option${role==='Quero ensinar'?' selected':''}>Quero ensinar</option><option${role==='Quero indicar'?' selected':''}>Quero indicar</option><option${role==='Quero fazer os dois'?' selected':''}>Quero fazer os dois</option></select></label><label>Nome<input type="text" placeholder="Seu nome" autocomplete="off"></label><label>Instagram ou canal<input type="text" placeholder="@seuperfil" autocomplete="off"></label><label>Principal modalidade ou comunidade<input type="text" placeholder="Ex.: corrida, altinha, musculação" autocomplete="off"></label><button class="button" type="button" data-submit-partner>Simular candidatura ${I('arrow')}</button></div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal()}
function completePartnerApplication(){document.getElementById('dialog-content').innerHTML=`<div class="dialog-content"><div class="dialog-emblem">${I('check')}</div><span class="pill subtle">SIMULAÇÃO CONCLUÍDA</span><h2 id="dialog-title">Seu movimento pode crescer aqui.</h2><p>Na versão final, a candidatura seguirá para verificação e o acompanhamento ficará disponível no painel Citra Partners.</p><p>Nenhum dado desta demonstração foi enviado ou salvo.</p><button class="button" data-close-dialog>Continuar explorando ${I('arrow')}</button></div>`;dialog.setAttribute('aria-labelledby','dialog-title');hydrateIcons(dialog)}
function openDialog(title,body,tag='Em breve'){lastDialogTrigger=document.activeElement;document.getElementById('dialog-content').innerHTML=`<div class="dialog-content"><div class="dialog-emblem">${I('lock')}</div><span class="pill subtle">${tag}</span><h2 id="dialog-title">${title}</h2>${body}<button class="button" data-close-dialog>Continuar explorando ${I('arrow')}</button></div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal()}

function feed(){const people=[['jadiel-futevolei.jpg','Jadiel','LIVE'],['jadiel-musculacao.jpg','Treino Pro','NOVO'],['evento-trilha.webp','Trilhas','HOJE'],['rio-beach.jpg','Rio Beach','12 KM'],['gym-strength.jpg','Academia','META']];return `${heading('Seu movimento inspira o próximo.','Atividades, profissionais, desafios e histórias da comunidade Citra.')}<section class="feed-now" aria-label="Agora no Citra"><div class="feed-now-head"><div><span class="eyebrow lime">AGORA NO CITRA</span><strong>Gente em movimento</strong></div><a href="#lives" class="text-link">Ver lives ${I('arrow')}</a></div><div class="feed-stories">${people.map(([img,name,status],i)=>`<button class="feed-story" ${i===0?'data-open-live':''} aria-label="Abrir atualização de ${name}"><span class="story-ring ${i===0?'is-live':''}"><img src="assets/${img}" alt="" loading="lazy"></span><strong>${name}</strong><small>${status}</small></button>`).join('')}</div></section><div class="feed-toolbar"><div class="feed-tabs" role="tablist" aria-label="Escolher conteúdo do feed"><button class="active" data-feed-filter="para-voce" role="tab" aria-selected="true">Para você</button><button data-feed-filter="seguindo" role="tab" aria-selected="false">Seguindo</button><button data-feed-filter="perto" role="tab" aria-selected="false">Perto de você</button></div><span class="pill subtle">${I('spark')} FEED DEMO</span></div><div class="feed-layout"><div class="feed-main"><section class="composer"><div class="composer-top"><span class="feed-avatar">L</span><button data-new-post>Como foi o seu treino hoje?</button></div><div class="composer-actions"><button data-new-post>${I('camera')} Foto</button><button data-new-post>${I('chart')} Marcar atividade</button><button data-new-post>${I('spark')} Compartilhar evolução</button></div></section><article class="post-card professional-post" data-feed-scope="para-voce seguindo"><div class="post-head"><span class="feed-avatar jadiel-avatar"><img src="assets/jadiel-futevolei.jpg" alt="Jadiel Ferreira"></span><div><strong>Jadiel Ferreira <span class="verified-mark" aria-label="Profissional verificado">✓</span></strong><span>Futevôlei · agora mesmo</span></div><button class="follow-chip" data-follow>Seguir</button></div><p>Movimento, controle e consistência. Hoje a missão foi dominar o primeiro toque na areia. Quem treinou também? ⚡</p><img class="post-image" src="assets/jadiel-futevolei.jpg" alt="Jadiel Ferreira com uma bola na quadra"><div class="post-workout-summary"><div>${I('clock')}<span><small>DURAÇÃO</small><strong>52 min</strong></span></div><div>${I('bolt')}<span><small>INTENSIDADE</small><strong>Alta</strong></span></div><div>${I('target')}<span><small>FOCO</small><strong>Técnica</strong></span></div></div><div class="post-social-proof"><span>❤️ 🔥 ⚡</span><span>1.284 reações · 96 comentários</span></div><div class="post-actions"><button data-feed-like data-count="1284">${I('heart')} <span>1.284</span></button><button data-feed-comment="Treino do Jadiel" data-count="96">${I('comment')} <span>96 comentários</span></button><button data-share-demo>${I('arrow')} Compartilhar</button></div></article><article class="post-card" data-feed-scope="para-voce seguindo perto"><div class="post-head"><span class="feed-avatar">MC</span><div><strong>Marina Costa</strong><span>Corrida · hoje, 07:12 · perto de você</span></div><span class="pill subtle">NOVO RECORDE</span></div><p>Primeiros 5 km sem parar. Achei que não ia conseguir, mas fui até o fim. Próxima meta: correr com a galera da orla. 🏃‍♀️</p><div class="mini-route"><div class="route-grid"></div><span class="route-path"></span><span class="route-pin start"></span><span class="route-pin finish"></span><span class="route-place">Copacabana · Rio de Janeiro</span></div><div class="post-stats"><strong>5,02 km</strong><span>31:44</span><span>6:19/km</span><span>+42 m</span></div><div class="post-social-proof"><span>👏 💚</span><span>214 reações · 18 comentários</span></div><div class="post-actions"><button data-feed-like data-count="214">${I('heart')} <span>214</span></button><button data-feed-comment="Corrida da Marina" data-count="18">${I('comment')} <span>18 comentários</span></button><button data-share-demo>${I('arrow')} Compartilhar</button></div></article><article class="post-card feed-event-post" data-feed-scope="para-voce perto"><img class="feed-event-image" src="assets/evento-trilha.webp" alt="Comunidade em uma trilha"><div class="feed-event-copy"><span class="eyebrow lime">ENCONTRO DA COMUNIDADE · DEMO</span><h2>Fora do asfalto.</h2><p>Uma prévia do encontro para quem quer trocar a cidade por novos caminhos e se movimentar em grupo.</p><div class="event-mini-meta"><span>${I('event')} Em preparação</span><span>${I('users')} Comunidade</span><span>${I('run')} Corrida</span></div><a class="button secondary" href="#eventos">Explorar eventos ${I('arrow')}</a></div></article></div><aside class="feed-side"><section class="feed-challenge"><span class="eyebrow">DESAFIO DA SEMANA</span><h2>3 movimentos.<br>7 dias.</h2><p>Complete três atividades em uma semana e mantenha sua sequência viva.</p><div class="challenge-progress"><span style="width:66%"></span></div><div class="challenge-meta"><strong>2 de 3</strong><span>Falta só mais uma</span></div><button class="button dark-button" data-challenge-demo>Entrar no desafio</button></section><section class="settings-card feed-ranking"><div class="section-heading"><div><span class="eyebrow lime">EM ALTA</span><h3>Movimento da semana</h3></div></div>${[['1','JS','Joana Silva','4 atividades'],['2','RF','Rafael Freire','38,4 km'],['3','MC','Marina Costa','3 recordes']].map(([pos,av,name,metric])=>`<div class="rank-row"><span class="rank-position">${pos}</span><span class="feed-avatar">${av}</span><span><strong>${name}</strong><small>${metric}</small></span></div>`).join('')}<p class="small muted">Ranking ilustrativo desta demonstração.</p></section><section class="feed-nearby"><span class="eyebrow lime">PERTO DE VOCÊ</span><strong>12 pessoas se movimentando agora</strong><p>Descubra atividades públicas e grupos quando o recurso estiver disponível.</p><button class="text-link" data-feed-filter="perto">Ver movimento local ${I('arrow')}</button></section></aside></div>`}

function lives(){const seeded=[['BR','Bruno Rocha','Esse treino de pernas está pegando 🔥'],['MC','Marina Costa','Jadiel, mostra a postura certa no agachamento!'],['JS','Joana Silva','Acompanhando de casa ⚡'],['LF','Lucas Freire','Qual é a próxima série?']];return `${heading('Ao vivo, junto com eles.','Treinos, perguntas, reações e bastidores em uma experiência em tempo real.')}<div class="live-room"><section class="live-stage"><img src="assets/jadiel-musculacao.jpg" alt="Jadiel Ferreira treinando na academia"><div class="live-stage-shade"></div><div class="live-stage-top"><span class="live-badge"><span class="live-dot"></span> LIVE DEMO</span><span class="viewer-count">${I('users')} <strong id="live-viewers">1.247</strong></span></div><div class="live-stage-copy"><span class="eyebrow">MUSCULAÇÃO · JADIEL FERREIRA</span><h1>Treino completo<br>sem cortes.</h1><p>Costas e bíceps com explicações durante cada série.</p><div class="live-host"><span class="feed-avatar"><img src="assets/jadiel.jpg" alt=""></span><span><strong>Jadiel Ferreira <b>✓</b></strong><small>Profissional Citra</small></span><button data-follow>Seguir</button></div></div><div class="reaction-float-zone" aria-hidden="true"></div></section><aside class="live-chat"><div class="live-chat-head"><div><strong>Chat ao vivo</strong><span><i></i> Conversa acontecendo agora</span></div><button data-live-info aria-label="Informações da demonstração">${I('info')}</button></div><div class="live-comments" id="live-comments" aria-live="polite">${seeded.map(([av,name,text])=>`<div class="live-comment"><span class="feed-avatar">${av}</span><p><strong>${name}</strong>${text}</p></div>`).join('')}</div><div class="live-reactions" aria-label="Reagir à live"><button data-live-reaction="🔥" aria-label="Enviar fogo">🔥</button><button data-live-reaction="👏" aria-label="Enviar aplausos">👏</button><button data-live-reaction="⚡" aria-label="Enviar raio">⚡</button><button data-live-reaction="💚" aria-label="Enviar coração verde">💚</button></div><div class="live-comment-box"><label class="sr-only" for="live-comment-input">Escreva um comentário</label><input id="live-comment-input" type="text" maxlength="100" placeholder="Comente na live..." autocomplete="off"><button data-send-live-comment aria-label="Enviar comentário">${I('arrow')}</button></div><small class="live-demo-note">Comentários simulados. Nada é enviado ou armazenado.</small></aside></div><section class="section live-schedule"><div class="section-heading"><div><span class="eyebrow lime">PRÓXIMAS TRANSMISSÕES</span><h2>Tem movimento marcado.</h2><p>Agenda demonstrativa — sem data ou horário confirmado.</p></div><button class="filter-chip" data-live-notify>${I('bolt')} Ativar lembretes</button></div><div class="live-grid">${[['jadiel-futevolei.jpg','Treino','Futevôlei na prática','Jadiel Ferreira','AREIA'],['evento-trilha.webp','IRL','Dia de trilha com a comunidade','Profissionais Citra','AO AR LIVRE'],['rio-beach.jpg','Lifestyle','Rotina, praia e movimento','Criadores Citra','BASTIDORES']].map(([img,cat,title,who,tag])=>`<article class="live-card"><div class="live-thumb"><img src="assets/${img}" alt="Prévia de ${cat.toLowerCase()}"><span class="pill">${I('lock')} EM BREVE</span><span class="live-play">${icon('play')}</span></div><div><span class="eyebrow">${cat} · ${tag}</span><h3>${title}</h3><p>${who}</p><button class="live-reminder" data-live-notify>${I('bolt')} Quero ser avisado</button></div></article>`).join('')}</div></section><div class="notice section">${I('info')}<div><strong>Uma prévia de como será assistir junto.</strong><br>A transmissão, o chat, as reações, a contagem de pessoas e a agenda nesta tela são demonstrativos. As lives serão liberadas a profissionais que cumprirem os critérios da Citra.</div></div>`}

function safeText(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function setFeedMode(mode,source){feedMode=mode;document.querySelectorAll('[data-feed-filter]').forEach(button=>{const active=button.dataset.feedFilter===mode;button.classList.toggle('active',active);if(button.getAttribute('role')==='tab')button.setAttribute('aria-selected',String(active))});document.querySelectorAll('[data-feed-scope]').forEach(post=>{post.hidden=!post.dataset.feedScope.split(' ').includes(mode)});if(source&&!source.closest('.feed-tabs'))document.querySelector('.feed-toolbar')?.scrollIntoView({behavior:'smooth',block:'start'})}
function toggleFeedLike(button){const liked=button.classList.toggle('liked');const base=Number(button.dataset.count)||0;const total=base+(liked?1:0);button.querySelector('span').textContent=total.toLocaleString('pt-BR');button.setAttribute('aria-pressed',String(liked))}
function openFeedComment(button){pendingFeedCommentButton=button;lastDialogTrigger=button;const title=button.dataset.feedComment||'Atividade';document.getElementById('dialog-content').innerHTML=`<div class="dialog-content composer-dialog"><div class="dialog-emblem">${I('comment')}</div><span class="pill subtle">COMENTÁRIO DEMO</span><h2 id="dialog-title">Entre na conversa.</h2><p>Comentando em: <strong>${safeText(title)}</strong></p><label>Seu comentário<textarea id="feed-comment-input" rows="4" maxlength="180" placeholder="Escreva algo positivo..."></textarea></label><button class="button" data-submit-feed-comment>Comentar ${I('arrow')}</button></div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();setTimeout(()=>document.getElementById('feed-comment-input')?.focus(),80)}
function submitFeedComment(){const input=document.getElementById('feed-comment-input');if(!input?.value.trim()){input?.focus();return}if(pendingFeedCommentButton){const count=Number(pendingFeedCommentButton.dataset.count)||0;pendingFeedCommentButton.dataset.count=String(count+1);pendingFeedCommentButton.querySelector('span').textContent=`${count+1} comentários`}dialog.close();pendingFeedCommentButton=null}
function appendLiveComment(name,text,own=false){const container=document.getElementById('live-comments');if(!container)return;const initials=own?'VC':name.split(' ').map(part=>part[0]).slice(0,2).join('').toUpperCase();container.insertAdjacentHTML('beforeend',`<div class="live-comment ${own?'is-own':''}"><span class="feed-avatar">${safeText(initials)}</span><p><strong>${safeText(name)}</strong>${safeText(text)}</p></div>`);while(container.children.length>9)container.firstElementChild.remove();container.scrollTo({top:container.scrollHeight,behavior:'smooth'})}
function startLiveComments(){clearInterval(liveCommentTimer);const comments=[['Bia Santos','Esse é o ritmo! 💚'],['Caio Lima','Cheguei agora, qual série estamos?'],['Nina Alves','A explicação fez toda diferença 👏'],['Pedro M.','Já salvei esse treino'],['Ana Clara','Manda um salve pra galera da corrida!'],['Rafa Torres','A comunidade tá quente hoje ⚡']];let index=0;liveCommentTimer=setInterval(()=>{if(location.hash.slice(1).split('/')[0]!=='lives'){clearInterval(liveCommentTimer);return}const [name,text]=comments[index++%comments.length];appendLiveComment(name,text);const viewers=document.getElementById('live-viewers');if(viewers)viewers.textContent=(1247+(index%11)).toLocaleString('pt-BR')},3200)}
function sendLiveComment(){const input=document.getElementById('live-comment-input');const value=input?.value.trim();if(!value){input?.focus();return}appendLiveComment('Você',value,true);input.value='';input.focus()}
function sendLiveReaction(button){const stage=document.querySelector('.live-stage');const zone=document.querySelector('.reaction-float-zone');if(!stage||!zone)return;const reaction=document.createElement('span');reaction.className='floating-reaction';reaction.textContent=button.dataset.liveReaction;reaction.style.left=`${58+Math.random()*28}%`;zone.appendChild(reaction);setTimeout(()=>reaction.remove(),1900)}
function afterRender(){enhancePartners();const route=location.hash.slice(1).split('/')[0]||'inicio';if(route==='lives')startLiveComments();else clearInterval(liveCommentTimer);if(route==='feed')setFeedMode(feedMode)}
document.getElementById('desktop-nav').innerHTML=navItems.map(([id,title,ic],i)=>`${i===7?'<div class="nav-separator"></div>':''}<a class="nav-item" href="#${id}" data-nav="${id}">${I(ic)}${title}${id==='evolucao'?`<i class="nav-lock">${icon('lock')}</i>`:''}</a>`).join('');
const mobileNavItems=[['inicio','Início','home'],['feed','Feed','feed'],['gravar','Gravar','map'],['eventos','Eventos','event'],['club','Club','club'],['mais','Mais','more']];
document.getElementById('mobile-nav').innerHTML=`<span class="mobile-nav-indicator" aria-hidden="true"><span></span></span>${mobileNavItems.map(([id,t,ic])=>`<a href="#${id}" data-nav="${id}"${id==='club'?' class="mobile-club-link"':''}>${I(ic)}<span>${t}</span></a>`).join('')}`;
function updateMobileNavIndicator(route){const nav=document.getElementById('mobile-nav');if(!nav)return;const routeMap={treinos:'inicio',treino:'inicio',modalidade:'inicio',lives:'mais',afiliados:'mais',lancamento:'mais','boas-vindas':'mais',evolucao:'mais'};const wanted=routeMap[route]||route;const index=Math.max(0,mobileNavItems.findIndex(([id])=>id===wanted));nav.style.setProperty('--indicator-x',`${index*100}%`);nav.querySelectorAll('[data-nav]').forEach(link=>{const active=link.dataset.nav===wanted;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')})}
document.getElementById('theme-toggle').addEventListener('click',toggleTheme);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-theme-toggle'))toggleTheme();if(b.hasAttribute('data-sport')){currentSport=b.dataset.sport;main.innerHTML=`<div class="fade-in">${trainings()}</div>`;const target=main.querySelector(`[data-sport="${currentSport}"]`);target?.focus({preventScroll:true})}if(b.hasAttribute('data-reset-events')){eventFilters={sport:'Todos',environment:'Todos',profile:'Todos'};main.innerHTML=eventPage();updateEventCount();main.querySelector('[data-reset-events]')?.focus({preventScroll:true})}if(b.hasAttribute('data-event')){const event=events[Number(b.dataset.event)];if(event)openDialog(event.name,`<p>${event.description}</p><p><strong>${event.sport} · ${event.environment} · ${event.profile}</strong></p><p>Esta é uma experiência prevista. Inscrições, datas, locais e condições de participação serão divulgados quando houver confirmação.</p>`,'Experiência prevista')}if(b.hasAttribute('data-future'))openDialog(b.dataset.future,'<p>Esta área está em desenvolvimento. Novos conteúdos e recursos serão apresentados no Citra Fit conforme forem disponibilizados.</p>','Em desenvolvimento');if(b.hasAttribute('data-club'))openDialog('Seu próximo capítulo, com o Club.','<p>Os planos e benefícios do Citra Club serão anunciados aqui. Você poderá consultar todas as condições antes de participar.</p><p>Os direitos de quem comprou na pré-venda serão definidos na oferta oficial.</p>');if(b.hasAttribute('data-affiliate'))openDialog('Vamos crescer juntos.','<p>O Citra Partners está sendo preparado para profissionais, criadores e pessoas que desejam indicar o ecossistema.</p>');if(b.hasAttribute('data-partner-preview'))openPartnerPreview(b.dataset.partnerPreview);if(b.hasAttribute('data-partner-apply'))openPartnerApplication(b.dataset.partnerApply);if(b.hasAttribute('data-submit-partner'))completePartnerApplication();if(b.hasAttribute('data-copy-demo')){navigator.clipboard?.writeText('https://citra.fit/seuusuario');b.innerHTML=I('check');b.closest('.fake-link')?.classList.add('copied')}if(b.hasAttribute('data-live-notify'))openDialog('Você não vai perder a próxima.','<p>Quando as lives estiverem ativas, seguidores poderão receber o aviso do profissional dentro do Citra Fit.</p>','Lives em breve');if(b.hasAttribute('data-new-post'))openPostComposer();if(b.hasAttribute('data-publish-demo'))publishDemoPost();if(b.hasAttribute('data-locate'))locateVisitor();if(b.hasAttribute('data-record-start'))toggleRecording(b);if(b.hasAttribute('data-close-dialog')||b.classList.contains('dialog-close'))dialog.close()});
document.addEventListener('click',e=>{const filter=e.target.closest('[data-feed-filter]');if(filter)setFeedMode(filter.dataset.feedFilter,filter);const like=e.target.closest('[data-feed-like]');if(like)toggleFeedLike(like);const comment=e.target.closest('[data-feed-comment]');if(comment)openFeedComment(comment);if(e.target.closest('[data-submit-feed-comment]'))submitFeedComment();const reaction=e.target.closest('[data-live-reaction]');if(reaction)sendLiveReaction(reaction);if(e.target.closest('[data-send-live-comment]'))sendLiveComment();const follow=e.target.closest('[data-follow]');if(follow){const active=follow.classList.toggle('active');follow.textContent=active?'Seguindo':'Seguir'}if(e.target.closest('[data-open-live]'))location.hash='lives';if(e.target.closest('[data-share-demo]'))openDialog('Movimento pronto para circular.','<p>Na versão final, você poderá compartilhar a atividade dentro e fora do Citra Fit.</p>','Compartilhamento demo');if(e.target.closest('[data-challenge-demo]'))openDialog('Mais uma meta para movimentar a semana.','<p>Desafios, sequências e recompensas serão conectados às atividades registradas no Citra Fit.</p>','Desafio demo');if(e.target.closest('[data-live-info]'))openDialog('Esta sala é uma demonstração.','<p>Os comentários automáticos, número de espectadores e reações mostram como a experiência poderá funcionar. Nada desta tela é uma transmissão real.</p>','Live demo')});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='live-comment-input'){e.preventDefault();sendLiveComment()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-event-filter]')){eventFilters[e.target.dataset.eventFilter]=e.target.value;document.getElementById('event-results').innerHTML=eventResults();updateEventCount()}if(e.target.id==='post-photo'){document.getElementById('post-photo-name').textContent=e.target.files?.[0]?.name||'Nenhuma foto selecionada.'}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-adjust-location]');if(button)toggleManualAdjust(button)});
dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});dialog.addEventListener('close',()=>{if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus({preventScroll:true})});
function enhancePartners(){const cta=document.querySelector('.partner-cta');if(!cta||document.querySelector('.partner-levels-section'))return;cta.insertAdjacentHTML('beforebegin',`<section class="section partner-levels-section"><div class="section-heading"><div><h2>Do primeiro cadastro ao Citra Elite.</h2><p>Cada nível libera novas possibilidades dentro do ecossistema.</p></div></div><div class="partner-levels"><article><span>01</span>${I('spark')}<h3>Parceiro</h3><p>Perfil aprovado, link próprio e acesso ao painel demonstrativo.</p></article><article><span>02</span>${I('check')}<h3>Verificado</h3><p>Documentação, experiência e conteúdos analisados pela Citra.</p></article><article><span>03</span>${I('live')}<h3>Profissional Live</h3><p>Transmissões liberadas após critérios de qualidade e participação.</p></article><article><span>04</span>${I('medal')}<h3>Citra Elite</h3><p>Destaque, experiências especiais e presença em eventos selecionados.</p></article></div><div class="notice section">${I('info')}<div><strong>Conteúdo e atuação com responsabilidade.</strong><br>Credenciais profissionais serão verificadas quando a modalidade ou o serviço exigir. Criadores poderão compartilhar rotina, experiência e lifestyle dentro dos formatos permitidos.</div></div></section>`);hydrateIcons(cta.parentElement)}
window.addEventListener('hashchange',render);window.addEventListener('hashchange',()=>requestAnimationFrame(afterRender));hydrateIcons();render();requestAnimationFrame(afterRender);
